"""Finding the official upload of a song on YouTube (YouTube Data API v3).

This module only *finds and ranks* videos. Whether a video's audio may be
downloaded is decided separately in `acquire.py`.

Official signals used for ranking (a title containing "Official" alone is never enough):
* "<Artist> - Topic" channels: auto-generated by YouTube Music from the label's delivery
* the channel name matches the artist (incl. "<Artist>VEVO")
* `contentDetails.licensedContent`: the upload is claimed by a content owner
* duration close to the catalog (iTunes/Deezer) duration of the original recording
Covers, remixes, nightcore, sped-up/slowed, karaoke, live and lyric/fan uploads are penalised.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any

import requests

from . import config
from .textutil import norm, similarity, split_artists, strip_feat

API = "https://www.googleapis.com/youtube/v3"
_session = requests.Session()

# Versions that are not the original recording (title or description of the video).
_BAD_VERSION = re.compile(
    r"\b(cover|кавер|karaoke|караоке|remix|ремикс|rmx|mashup|nightcore|sped\s*up|speed\s*up|slowed|reverb|8d|"
    r"bass\s*boost(?:ed)?|live|лайв|концерт|konsert|concert|acoustic|акустик|instrumental|инструментал|minus|минус|"
    r"piano\s*version|guitar\s*version|tutorial|reaction|parody|пародия|teaser|trailer|snippet|preview|fan\s*made|"
    r"fanmade|edit|loop|1\s*hour|10\s*hours|tiktok\s*version)\b", re.I)
_LYRIC = re.compile(r"\b(lyrics?|lyric\s*video|текст|matn|karaoke)\b", re.I)
_OFFICIAL_VIDEO = re.compile(r"\bofficial\s+(?:music\s+)?video\b|\bофициальн\w*\s+(?:видео|клип)\b|\brasmiy\s+klip\b", re.I)
_OFFICIAL_AUDIO = re.compile(r"\bofficial\s+audio\b|\baudio\s+officiel\b", re.I)
_DURATION = re.compile(r"^P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$")


class YouTubeError(RuntimeError):
    pass


@dataclass
class Video:
    id: str
    title: str
    channel_id: str
    channel: str
    duration: float = 0.0
    license: str = "youtube"          # "youtube" (standard licence) or "creativeCommon"
    licensed_content: bool = False    # claimed by a content owner (label / distributor)
    description: str = ""
    thumbnail: str | None = None
    score: float = 0.0
    kind: str = ""                    # "topic" | "official-audio" | "official-video" | "artist-channel" | "other"
    official: bool = False
    reasons: list[str] = field(default_factory=list)

    @property
    def url(self) -> str:
        return f"https://www.youtube.com/watch?v={self.id}"

    def as_dict(self) -> dict[str, Any]:
        return {"id": self.id, "title": self.title, "channel": self.channel, "channel_id": self.channel_id,
                "duration": self.duration, "license": self.license, "licensed_content": self.licensed_content,
                "thumbnail": self.thumbnail, "score": round(self.score, 3), "kind": self.kind,
                "official": self.official, "url": self.url}

    @classmethod
    def from_dict(cls, data: dict) -> "Video":
        keep = {k: data[k] for k in ("id", "title", "channel_id", "channel", "duration", "license",
                                     "licensed_content", "thumbnail", "score", "kind", "official") if k in data}
        return cls(**keep)


def available() -> bool:
    return bool(config.YOUTUBE_API_KEY)


def parse_duration(value: str) -> float:
    match = _DURATION.match(value or "")
    if not match:
        return 0.0
    d, h, m, s = (int(x or 0) for x in match.groups())
    return float(((d * 24 + h) * 60 + m) * 60 + s)


def _api(path: str, params: dict) -> dict:
    if not config.YOUTUBE_API_KEY:
        raise YouTubeError("YOUTUBE_API_KEY sozlanmagan")
    try:
        resp = _session.get(f"{API}/{path}", params={**params, "key": config.YOUTUBE_API_KEY}, timeout=20)
    except requests.RequestException as exc:
        raise YouTubeError(f"YouTube API: tarmoq xatosi ({type(exc).__name__})") from None
    if resp.status_code != 200:
        reason = ""
        try:
            reason = ((resp.json().get("error") or {}).get("errors") or [{}])[0].get("reason", "")
        except ValueError:
            pass
        # Never echo the request URL: it carries the API key.
        raise YouTubeError(f"YouTube API: HTTP {resp.status_code} {reason}".strip())
    return resp.json()


def _artist_keys(artist: str) -> list[str]:
    return [norm(a) for a in split_artists(artist) if norm(a)] or ([norm(artist)] if norm(artist) else [])


def _channel_kind(channel: str, artist: str) -> tuple[str, float]:
    """How strongly the channel name says "this is the artist's / label's own channel"."""
    name = channel.strip()
    keys = _artist_keys(artist)
    topic = re.sub(r"\s*-\s*topic$", "", name, flags=re.I)
    if topic != name and any(similarity(topic, k) >= 0.88 for k in keys):
        return "topic", 1.0
    bare = re.sub(r"(?:vevo|official|music|tv|channel)$", "", norm(name).replace(" ", ""), flags=re.I)
    for key in keys:
        compact = key.replace(" ", "")
        if compact and (bare == compact or similarity(bare, compact) >= 0.9):
            return ("vevo" if "vevo" in name.lower() else "artist-channel"), 0.85
    return "other", 0.0


def score_video(video: Video, title: str, artist: str, duration: float) -> Video:
    """Fill video.score / kind / official / reasons. Pure function (unit-tested without network)."""
    reasons: list[str] = []
    want_title = strip_feat(title)[0]
    title_has_bad = _BAD_VERSION.search(video.title)
    want_has_bad = _BAD_VERSION.search(title)  # the user asked for a remix explicitly -> don't punish it

    # 1. Title: the song title must be in the video title.
    vt = norm(video.title)
    t_sim = 1.0 if norm(want_title) and norm(want_title) in vt else similarity(video.title, want_title)
    score = 0.35 * t_sim
    if t_sim < 0.55:
        reasons.append("nom mos emas")

    # 2. Artist: in the title or as the channel.
    kind, channel_score = _channel_kind(video.channel, artist)
    a_in_title = any(k and k in vt for k in _artist_keys(artist))
    score += 0.2 * max(channel_score, 1.0 if a_in_title else 0.0)
    if not a_in_title and not channel_score:
        reasons.append("ijrochi topilmadi")

    # 3. Official signals.
    if kind == "topic":
        score += 0.3
        video.kind = "topic"
    elif kind in ("artist-channel", "vevo"):
        score += 0.22
        video.kind = "artist-channel"
    if video.licensed_content:
        score += 0.08
    if kind != "other" and _OFFICIAL_VIDEO.search(video.title):
        score += 0.05
        video.kind = "official-video"
    elif kind != "other" and _OFFICIAL_AUDIO.search(video.title):
        score += 0.06
        video.kind = "official-audio"
    if not video.kind:
        video.kind = "other"

    # 4. Penalties: other versions, lyric/fan uploads.
    if title_has_bad and not want_has_bad:
        score -= 0.6
        reasons.append(f"boshqa versiya ({title_has_bad.group(0).lower()})")
    elif not want_has_bad and _BAD_VERSION.search(video.description[:200] or "") and kind == "other":
        score -= 0.15
    if _LYRIC.search(video.title) and kind == "other":
        score -= 0.25
        reasons.append("norasmiy lyric video")
    if kind == "other" and not video.licensed_content:
        score -= 0.15  # someone's re-upload: no channel identity, no content-owner claim

    # 5. Duration vs the catalog duration of the original recording.
    if duration and video.duration:
        diff = video.duration - duration
        if abs(diff) <= 6:
            score += 0.1
        elif -20 <= diff <= 75:  # music videos often carry an intro/outro
            score += 0.02
        else:
            score -= 0.35
            reasons.append(f"davomiyligi mos emas ({int(video.duration)}s / {int(duration)}s)")
    if video.duration and video.duration < 60:
        score -= 0.5
        reasons.append("juda qisqa (preview/shorts)")
    if video.duration > 15 * 60:
        score -= 0.5
        reasons.append("juda uzun (mix/albom)")

    video.score = score
    # Official = channel identity (topic / artist / VEVO) and nothing that says "another version".
    video.official = (kind != "other" and t_sim >= 0.6 and not (title_has_bad and not want_has_bad)
                      and score >= 0.7)
    video.reasons = reasons
    return video


def search(title: str, artist: str, duration: float = 0.0, limit: int = 15) -> list[Video]:
    """Search YouTube, read every candidate's details, return them best first."""
    query = f"{artist} {strip_feat(title)[0]}".strip()
    if not query:
        return []
    found = _api("search", {"part": "snippet", "q": query, "type": "video", "maxResults": max(5, min(25, limit)),
                            "videoCategoryId": "10", "safeSearch": "none"})
    ids = [item["id"]["videoId"] for item in found.get("items", [])
           if (item.get("id") or {}).get("videoId")]
    # A second, narrower query for the auto-generated "Topic" upload (official audio from the label).
    try:
        topic = _api("search", {"part": "snippet", "q": f"{query} topic", "type": "video", "maxResults": 5,
                                "videoCategoryId": "10"})
        ids += [item["id"]["videoId"] for item in topic.get("items", [])
                if (item.get("id") or {}).get("videoId") and item["id"]["videoId"] not in ids]
    except YouTubeError:
        pass
    if not ids:
        return []
    details = _api("videos", {"part": "snippet,contentDetails,status", "id": ",".join(ids[:50])})
    videos = []
    for item in details.get("items", []):
        snippet, content, status = item.get("snippet", {}), item.get("contentDetails", {}), item.get("status", {})
        if status.get("privacyStatus") not in (None, "public", "unlisted") or not status.get("embeddable", True):
            continue
        if (content.get("regionRestriction") or {}).get("allowed") == []:
            continue
        thumbs = snippet.get("thumbnails") or {}
        thumb = (thumbs.get("maxres") or thumbs.get("high") or thumbs.get("default") or {}).get("url")
        videos.append(score_video(Video(
            id=item["id"], title=snippet.get("title", ""), channel_id=snippet.get("channelId", ""),
            channel=snippet.get("channelTitle", ""), duration=parse_duration(content.get("duration", "")),
            license=status.get("license", "youtube"), licensed_content=bool(content.get("licensedContent")),
            description=snippet.get("description", ""), thumbnail=thumb), title, artist, duration))
    videos.sort(key=lambda v: (not v.official, -v.score))
    return videos


def best_official(videos: list[Video], duration: float = 0.0) -> Video | None:
    """Priority: official music video, official audio, artist's channel, label "Topic" upload.

    A music video whose length differs from the recording (an intro, a skit) would give an MP3 that is not the
    song as released, so then the official audio / Topic upload goes first.
    """
    official = [v for v in videos if v.official]
    if not official:
        return None

    def rank(v: Video) -> tuple:
        clean = not duration or not v.duration or abs(v.duration - duration) <= 6
        order = {"official-video": 0, "official-audio": 1, "artist-channel": 2, "topic": 3}.get(v.kind, 9)
        return (not clean, order, -v.score)

    return min(official, key=rank)
